python3 -I -c 'import hashlib, json, subprocess; files = subprocess.check_output(["git", "ls-files"], text=True).splitlines(); idx = json.load(open(".agent-receipts/udb-wave8-inputs-dux/prior/census-20261012-0454/source-index-enhanced.json")); idx_set = {n["source_id"] for n in idx["nodes"]}; m = {hashlib.sha256(f.encode()).hexdigest()[:24]: f for f in files}; matched = sorted((sid, m[sid]) for sid in idx_set if sid in m); print("matched_index_nodes:", len(matched), "of", len(idx_set)); print("pg_sh_match:", [x for x in matched if "pg" in x[1] or "restore" in x[1] or "migrate" in x[1]][:30])'
